import{z as i,x as s,o as B,c as F,q as l,j as t,D as e,d as a,s as n,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"错误恢复与重试","description":"","frontmatter":{"title":"错误恢复与重试","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-error-recovery.md","filePath":"llm/agent-error-recovery.md","lastUpdated":1791063341000}'),D={name:"llm/agent-error-recovery.md"};function m(C,E,d,h,p,f){const r=s("Mermaid");return B(),F("div",null,[E[2]||(E[2]=l('<h1 id="错误恢复与重试" tabindex="-1">错误恢复与重试 <a class="header-anchor" href="#错误恢复与重试" aria-label="Permalink to &quot;错误恢复与重试&quot;">​</a></h1><div class="epigraph"><p>「失败」不是一个类别；超时、坏 JSON、结果错误、原地打转是四种病，各有各的药，混着治只会越治越贵。</p><footer>—— 据 Shinn et al., Reflexion, NeurIPS 2023 的语言化反思机制；工程口径按失败分级整理</footer></div><p><a href="/llm/agent-multi-orchestration">上一课</a>把单环劈成多条，每条环各自会失败。本课把失败分级、给每级配恢复动作：不分级，恢复就是乱的——把瞬时错误当任务失败，成功率虚低；把语义错误当瞬时错误，无限重试烧穿预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失败至少分四级，恢复动作互不通用。<strong>基础设施失败</strong>：超时、限流、5xx、断连——错不在任务，重试是正确动作，但要有退避与幂等前提。<strong>协议失败</strong>：JSON 解不开、参数违反 schema、调用名不存在——重试同样的输入几乎必然再错，正确动作是把错误原文回喂让模型改参数（<a href="/llm/agent-tool-protocol-deep">工具协议深钻</a>的错误通道），或用 <a href="/llm/json-schema-decode">JSON / 结构化输出</a>的约束通道在源头消灭。<strong>语义失败</strong>：工具执行成功、返回 200，但结果不对——检索漏了、补丁没修好、订错了日期；这一级模型自己往往不知道错，靠结果重试是空转，必须先有验证器。<strong>策略失败</strong>：死循环、同一调用反复、目标漂移——个体动作全对，轨迹在错误的整体方向上收敛，退避和回喂都无效，需要熔断与换路。<span class="marginnote">直觉类比：这四级像快递出问题的四种原因——路上车祸（基础设施）、面单格式打错（协议）、送到了但不是你订的东西（语义）、骑手在你小区里绕第三圈（策略）。车祸重派一次就行，绕圈再派几次还是在绕，得换人。</span>评测口径要先钉住这四级怎么计入（<a href="/llm/agent-eval-protocol">智能体与工具评测协议</a>），否则「成功率」里混着四种不同的死法。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每级配最小恢复集。基础设施：指数退避加抖动，写操作带幂等键，重试次数与预算联动。<span class="marginnote">术语翻译：指数退避就是每次重试前把等待时间翻倍——第 1 次等 1 秒、第 2 次等 2 秒、第 3 次等 4 秒；「加抖动」是再叠一个随机量，让大量客户端不要在同一秒一起重试、把刚恢复的服务又打趴下。</span>协议：回喂上限两到三次，超限升级为策略失败处理。语义：验证器先行——任务自带的断言（测试、lint、对账）最硬；模型自检（<a href="/llm/self-verification-backtrack">自我验证与回溯</a>、<a href="/llm/self-critique-revise">自我批判与修订</a>）次之但会漏同源错误；判过仍失败，走跨尝试的教训沉淀：<a href="/llm/reflexion">Reflexion</a> 把失败语言化成「哪里错、下轮改什么」存进记忆，让下一次尝试条件化于上一次的死因。策略：熔断——同一工具同一参数重复出现即熔断；检查点——轨迹可从分叉点重放，不必从头再来；换路——换工具、换分解、或把决策交还给人。</p>',7)),(B(),t(o,null,{default:e(()=>[n(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%7B%22%E5%A4%B1%E8%B4%A5%E5%8F%91%E7%94%9F%E5%9C%A8%E5%93%AA%E4%B8%80%E7%BA%A7%3F%22%7D%20--%3E%20INFRA%5B%22%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD%EF%BC%9A%E9%80%80%E9%81%BF%20%2B%20%E6%8A%96%E5%8A%A8%20%2B%20%E5%B9%82%E7%AD%89%22%5D%0A%20%20FAIL%20--%3E%20PROTO%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E9%94%99%E8%AF%AF%E5%8E%9F%E6%96%87%E5%9B%9E%E5%96%82%20%2B%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20FAIL%20--%3E%20SEM%5B%22%E8%AF%AD%E4%B9%89%EF%BC%9A%E5%85%88%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%8C%E5%86%8D%E8%87%AA%E6%A3%80%22%5D%0A%20%20FAIL%20--%3E%20STRAT%5B%22%E7%AD%96%E7%95%A5%EF%BC%9A%E7%86%94%E6%96%AD%20%2F%20%E6%8D%A2%E8%B7%AF%20%2F%20%E9%97%AE%E4%BA%BA%22%5D%0A%20%20SEM%20--%3E%7C%22%E9%AA%8C%E8%AF%81%E4%B8%8D%E8%BF%87%E4%B8%94%E5%B0%9D%E8%AF%95%E8%80%97%E5%B0%BD%22%7C%20REF%5B%22%E5%A4%B1%E8%B4%A5%E6%95%99%E8%AE%AD%E5%85%A5%E8%AE%B0%E5%BF%86%EF%BC%88Reflexion%EF%BC%89%22%5D%0A%20%20REF%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%9D%A1%E4%BB%B6%E5%8C%96%E9%87%8D%E8%AF%95%22%5D%0A%20%20INFRA%20--%3E%20NEXT%0A%20%20PROTO%20--%3E%20NEXT%0A%20%20STRAT%20--%3E%20HUMAN%5B%22%E4%BA%BA%E5%B7%A5%E6%8E%A5%E7%AE%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("重试有效的统计前提是失败相互独立：温度不动、提示不动地再采样一次，遇到的是同一个难点，失败高度相关。所以「重试」要么改条件（换提示、换参数、换工具），要么承认这不是重试是空转。语义级验证器是恢复体系的分水岭：没有验证器，代理对「错但成功」的状态无从察觉，后续每一步都建立在坏状态上；有验证器，语义失败才从不可见变成可触发。Reflexion 的机制价值在把失败从「噪声」变成「经验」：执行轨迹是情景记忆（"),A("a",{href:"/llm/agent-memory-implementation"},"记忆系统的实现"),a("），提炼出的教训是程序性记忆——同一任务第 k 次尝试应当比第 1 次聪明，这是代理与纯函数采样器的本质差别。")],-1)),E[5]||(E[5]=A("p",null,[A("span",{class:"marginnote"},"幂等键给重试授权：查询类工具天然可重试；写入类工具没有幂等键时，「超时后重试」可能在服务端成功两次。工具描述应写明幂等语义，编排器据此决定哪类失败允许自动重试。")],-1)),(B(),t(o,null,{default:e(()=>[n(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E5%B7%A5%E5%85%B7%E8%BF%94%E5%9B%9E%20200%EF%BC%8C%E4%BD%86%E7%BB%93%E6%9E%9C%E4%B8%8D%E5%AF%B9%EF%BC%88%E8%AF%AD%E4%B9%89%E5%A4%B1%E8%B4%A5%EF%BC%89%22%5D%20--%3E%20CHK%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%E9%AA%8C%E8%AF%81%E5%99%A8%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%B2%A1%E6%9C%89%EF%BC%9A%E9%94%99%E8%AF%AF%E4%B8%8D%E5%8F%AF%E8%A7%81%22%7C%20BAD%5B%22%E5%90%8E%E7%BB%AD%E6%AF%8F%E4%B8%80%E6%AD%A5%E9%83%BD%E7%9B%96%E5%9C%A8%E5%9D%8F%E7%8A%B6%E6%80%81%E4%B8%8A%22%5D%0A%20%20BAD%20--%3E%20WORSE%5B%22%E9%94%99%E8%AF%AF%E6%BB%9A%E9%9B%AA%E7%90%83%EF%BC%8C%E7%9B%B4%E5%88%B0%E4%BB%BB%E5%8A%A1%E5%A4%B1%E8%B4%A5%E4%B9%9F%E8%AF%B4%E4%B8%8D%E6%B8%85%E6%AD%BB%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%9C%89%EF%BC%9A%E6%96%AD%E8%A8%80%20%2F%20%E6%B5%8B%E8%AF%95%20%2F%20%E5%AF%B9%E8%B4%A6%22%7C%20CATCH%5B%22%E5%BD%93%E5%9C%BA%E6%8B%A6%E6%88%AA%EF%BC%8C%E7%8A%B6%E6%80%81%E6%9C%AA%E6%89%A9%E6%95%A3%22%5D%0A%20%20CATCH%20--%3E%20FEED%5B%22%E9%87%8D%E5%81%9A%E8%AF%A5%E6%AD%A5%EF%BC%8C%E6%88%96%E6%8A%8A%E6%AD%BB%E5%9B%A0%E8%AF%AD%E8%A8%80%E5%8C%96%E5%85%A5%E8%AE%B0%E5%BF%86%22%5D%0A%20%20FEED%20--%3E%20BETTER%5B%22%E4%B8%8B%E4%B8%80%E6%AC%A1%E5%B0%9D%E8%AF%95%E6%9D%A1%E4%BB%B6%E5%8C%96%E4%BA%8E%E4%B8%8A%E4%B8%80%E6%AC%A1%E7%9A%84%E6%95%99%E8%AE%AD%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>恢复不能掩盖系统性缺陷：重试成功次数要单独记账，占比高说明提示、工具或 schema 该修，而不是让重试兜底。验证器也有自己的失败模式：断言写得松，语义失败漏网；写得紧，正确解被误杀——τ-bench 用 \\(\\mathrm{pass}^k\\) 把「稳定做对」与「偶尔蒙对」分开（<a href="/llm/taubench-agentbench">τ-bench / AgentBench</a>），恢复设计的最终目的正是把后者变成前者。<span class="marginnote">数字实例：\\(\\mathrm{pass}^k\\) 要求 \\(k\\) 次独立运行全部通过。单次成功率 80% 的代理，\\(k=3\\) 时只剩 \\(0.8^3 \\approx 51\\%\\)；\\(k=5\\) 时跌到约 33%。看似不错的「八成把握」在连续任务里会迅速缩水，这就是为什么指标要按 \\(k\\) 报。</span>人工接管不是失败：接管的触发点、等待时长与交接上下文都该是显式设计（<a href="/llm/agent-guardrails">安全围栏</a>会把不可逆动作的卡点制度化）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失败四级：基础设施、协议、语义、策略；每级恢复动作不同，先分级再动手。</li><li>重试有效的前提是失败独立；不改条件的重试是相关失败上的空转。</li><li>语义失败的入口是验证器：没有验证器，代理在坏状态上继续盖楼。</li><li>Reflexion 把死因语言化入记忆，让第 k 次尝试条件化于前 k−1 次。</li><li>熔断、检查点、人工接管是策略级的三件套，触发阈值显式化。</li><li>出处：失败分级与退避重试为工程口径；Reflexion 见 Shinn et al., NeurIPS 2023。</li></ul>',4))])}const u=i(D,[["render",m]]);export{g as __pageData,u as default};
